// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

contract MyDAO is Initializable, Ownable, Pausable {
    using SafeMath for uint256;

    // Variables for DAO parameters
    uint256 public quorum;
    uint256 public votingPeriod;

    // Structs for proposals and votes
    struct Proposal {
        string description;
        address proposer;
        uint256 votingDeadline;
        bool executed;
        bool proposalPassed;
        uint256 numberOfVotes;
        uint256 currentResult;
        mapping (address => bool) voted;
    }

    struct Voter {
        uint256 vote;
        bool voted;
    }

    // Variables for proposals and votes
    uint256 public numProposals;
    mapping (uint256 => Proposal) public proposals;
    mapping (address => Voter) public voters;

    // Event for new proposal
    event NewProposal(uint256 proposalId, string description, address proposer);

    // Modifier to check if voting is still ongoing
    modifier votingOpen(uint256 _proposalId) {
        require(block.timestamp <= proposals[_proposalId].votingDeadline, "Voting period has ended");
        _;
    }

    // Modifier to check if the proposal has not been executed yet
    modifier notExecuted(uint256 _proposalId) {
        require(!proposals[_proposalId].executed, "Proposal has already been executed");
        _;
    }

    // Function to initialize DAO parameters
    function initialize(uint256 _quorum, uint256 _votingPeriod) public initializer {
        require(_quorum > 0 && _quorum <= 100, "Quorum must be between 1 and 100");
        require(_votingPeriod > 0, "Voting period must be greater than 0");
        quorum = _quorum;
        votingPeriod = _votingPeriod;
    }
